import json

from google.cloud import monitoring_v3

from observability_client import get_monitoring_client
from observability_models import MetricPoint

def aggregate_metric_stats(payload, config=None):
    config = config or {}
    client = get_monitoring_client()

    # Default aggregation to MEAN and REDUCE_MEAN if not provided
    aligner = getattr(monitoring_v3.Aggregation.Aligner, payload.get("aligner", "ALIGN_MEAN").upper())
    reducer = getattr(monitoring_v3.Aggregation.Reducer, payload.get("reducer", "REDUCE_MEAN").upper())

    aggregation = {
        "alignment_period": {"seconds": config.get("period_seconds", 60)},
        "per_series_aligner": aligner,
        "cross_series_reducer": reducer,
        "group_by_fields": payload.get("group_by_fields", [])
    }

    series = client.list_time_series(request={
        "name": f"projects/{config['project_id']}",
        "filter": "metric.type = " + json.dumps(payload["metric"]),
        "interval": {
            "start_time": {"seconds": int(payload["start_time"])
            },
            "end_time": {"seconds": int(payload["end_time"])}
        },
        "aggregation": aggregation,
        "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL
    })

    aggregated_data = []
    for timeseries in series:
        for point in timeseries.points:
            kind = point.value._pb.WhichOneof("value")
            if kind not in ("double_value", "int64_value"):
                raise ValueError("Expected a scalar numeric metric")
            aggregated_data.append({"timestamp": point.interval.end_time.timestamp(), "value": float(getattr(point.value, kind))})
    return {"aggregated_points": sorted(aggregated_data, key=lambda p: p["timestamp"])}

import json

from google.cloud import monitoring_v3

from observability_client import get_monitoring_client
from observability_models import MetricPoint

def filter_metric_dimensions(payload, config=None):
    config = config or {}
    client = get_monitoring_client()

    metric_filter = "metric.type = " + json.dumps(payload["metric"])
    dimension_filters = []
    if "resource_labels" in payload:
        for key, value in payload["resource_labels"].items():
            dimension_filters.append(f"resource.labels.{key} = " + json.dumps(value))
    if "metric_labels" in payload:
        for key, value in payload["metric_labels"].items():
            dimension_filters.append(f"metric.labels.{key} = " + json.dumps(value))

    full_filter = metric_filter
    if dimension_filters:
        full_filter += " AND " + " AND ".join(dimension_filters)

    series = client.list_time_series(request={
        "name": f"projects/{config['project_id']}",
        "filter": full_filter,
        "interval": {
            "start_time": {"seconds": int(payload["start_time"])}
            ,
            "end_time": {"seconds": int(payload["end_time"])}
        },
        "aggregation": {
            "alignment_period": {"seconds": config.get("period_seconds", 60)},
            "per_series_aligner": monitoring_v3.Aggregation.Aligner.ALIGN_MEAN
        },
        "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL
    })

    filtered_data = []
    for timeseries in series:
        points = []
        for point in timeseries.points:
            kind = point.value._pb.WhichOneof("value")
            if kind not in ("double_value", "int64_value"):
                raise ValueError("Expected a scalar numeric metric")
            points.append(MetricPoint(timestamp=point.interval.end_time.timestamp(), value=float(getattr(point.value, kind))))

        resource_labels = {k: v for k, v in timeseries.resource.labels.items()}
        metric_labels = {k: v for k, v in timeseries.metric.labels.items()}

        filtered_data.append({
            "resource_labels": resource_labels,
            "metric_labels": metric_labels,
            "points": [p.__dict__ for p in points] # Convert MetricPoint to dict for serialization
        })

    return {"filtered_series": filtered_data}

import json

from google.cloud import monitoring_v3

from observability_client import get_monitoring_client
from observability_models import MetricPoint

def _fetch_series(client, project_id, metric_type, start_time, end_time, filter_string, period_seconds):
    full_filter = f"metric.type = {json.dumps(metric_type)}"
    if filter_string:
        full_filter += f" AND {filter_string}"

    series = client.list_time_series(request={
        "name": f"projects/{project_id}",
        "filter": full_filter,
        "interval": {
            "start_time": {"seconds": int(start_time)}
            ,
            "end_time": {"seconds": int(end_time)}
        },
        "aggregation": {
            "alignment_period": {"seconds": period_seconds},
            "per_series_aligner": monitoring_v3.Aggregation.Aligner.ALIGN_MEAN
        },
        "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL
    })

    data_points = []
    for timeseries in series:
        for point in timeseries.points:
            kind = point.value._pb.WhichOneof("value")
            if kind not in ("double_value", "int64_value"):
                raise ValueError("Expected a scalar numeric metric")
            data_points.append(MetricPoint(timestamp=point.interval.end_time.timestamp(), value=float(getattr(point.value, kind))))
    return sorted(data_points, key=lambda p: p.timestamp)

def compare_metric_series(payload, config=None):
    config = config or {}
    client = get_monitoring_client()

    project_id = config["project_id"]
    metric_type = payload["metric"]
    start_time = payload["start_time"]
    end_time = payload["end_time"]
    period_seconds = config.get("period_seconds", 60)

    series1_data = _fetch_series(client, project_id, metric_type, start_time, end_time, payload["filter1"], period_seconds)
    series2_data = _fetch_series(client, project_id, metric_type, start_time, end_time, payload["filter2"], period_seconds)

    return {
        "series1": [p.__dict__ for p in series1_data],
        "series2": [p.__dict__ for p in series2_data],
    }

import json
import textwrap

from google.cloud import monitoring_v3

from observability_client import get_monitoring_client, get_generative_model
from observability_models import MetricPoint

def metric_summary(payload, config=None):
    config = config or {}
    monitoring_client = get_monitoring_client()
    generative_model = get_generative_model()

    metric_type = payload["metric"]
    start_time = payload["start_time"]
    end_time = payload["end_time"]
    project_id = config["project_id"]
    period_seconds = config.get("period_seconds", 60)

    # Fetch metric data
    series_data = monitoring_client.list_time_series(request={
        "name": f"projects/{project_id}",
        "filter": f"metric.type = {json.dumps(metric_type)}",
        "interval": {
            "start_time": {"seconds": int(start_time)}
            ,
            "end_time": {"seconds": int(end_time)}
        },
        "aggregation": {
            "alignment_period": {"seconds": period_seconds},
            "per_series_aligner": monitoring_v3.Aggregation.Aligner.ALIGN_MEAN
        },
        "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL
    })

    points = []
    for timeseries in series_data:
        for point in timeseries.points:
            kind = point.value._pb.WhichOneof("value")
            if kind not in ("double_value", "int64_value"):
                raise ValueError("Expected a scalar numeric metric")
            points.append(MetricPoint(timestamp=point.interval.end_time.timestamp(), value=float(getattr(point.value, kind))))

    # Prepare data for summary
    data_for_summary = ""
    if points:
        data_for_summary = "Metric points (timestamp, value):\n"
        for p in sorted(points, key=lambda p: p.timestamp):
            data_for_summary += f"- {p.timestamp}: {p.value}\n"
    else:
        data_for_summary = "No data points found for the given metric and time window."

    # Generate summary using the generative model
    prompt = textwrap.dedent(f"""
    Analyze the following metric data and provide a concise summary of trends or anomalies. 
    If no data is present, state that. 
    Metric Type: {metric_type}
    Start Time: {start_time}
    End Time: {end_time}

    {data_for_summary}

    Summary:
    """)

    response = generative_model.generate_content(prompt)
    summary = response.text

    return {"metric_summary": summary}

from observability_client import get_translate_client

def dashboard_note_translate(payload, config=None):
    config = config or {}
    client = get_translate_client()

    project_id = config["project_id"]
    location = "global" # Or a specific region if needed

    parent = f"projects/{project_id}/locations/{location}"

    text_to_translate = payload["text"]
    target_language = payload["target_language_code"]

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text_to_translate],
            "target_language_code": target_language,
        }
    )

    translated_text = ""
    if response.translations:
        translated_text = response.translations[0].translated_text

    return {"original_text": text_to_translate, "translated_text": translated_text, "target_language_code": target_language}
